// JAH demo program — Rapid-scene loop runner
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
var __steps=["Scan: 360-degree hazard sweep before entry", "Anchor: fix one safe reference point for the crew", "Communicate: one plain-language update on the radio", "Act: smallest useful intervention first", "Re-scan: verify the scene has not changed"];
__steps.forEach(function(s,i){console.log("step "+(i+1)+": "+s);});
check("step count", __steps.length, 5);
function loopOK(done){ return done===5?'loop complete — repeat':'loop incomplete'; }
check("all five done", loopOK(5), "loop complete \u2014 repeat");
check("three done", loopOK(3), "loop incomplete");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

