// JAH demo program — Matrix coverage
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function coverage(matrix){ var weak=0;
  Object.keys(matrix).forEach(function(pos){ var best=Math.max.apply(null, matrix[pos]); if(best<3)weak++; });
  return {positions:Object.keys(matrix).length, weak:weak}; }
var m=coverage({driver:[4,2],officer:[3,3],nozzle:[2,1],pump:[4,4]});
check("positions counted", m.positions, 4);
check("weak positions", m.weak, 1);
